import pathlib
PATCH = {
    'src/main/java/com/example/fpvdrone/registry/ModEntities.java': 'package com.example.fpvdrone.registry;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport net.minecraft.resources.ResourceLocation;\nimport net.minecraft.world.entity.EntityType;\nimport net.minecraft.world.entity.MobCategory;\nimport net.minecraftforge.registries.DeferredRegister;\nimport net.minecraftforge.registries.ForgeRegistries;\nimport net.minecraftforge.registries.RegistryObject;\n\npublic class ModEntities {\n    public static final DeferredRegister<EntityType<?>> ENTITY_TYPES =\n            DeferredRegister.create(ForgeRegistries.ENTITY_TYPES, FpvDroneMod.MODID);\n\n    public static final RegistryObject<EntityType<FpvDroneEntity>> FPV_DRONE =\n            ENTITY_TYPES.register("fpv_drone",\n                    () -> EntityType.Builder.<FpvDroneEntity>of(FpvDroneEntity::new, MobCategory.MISC)\n                            .sized(0.65F, 0.35F)\n                            .clientTrackingRange(64)\n                            .updateInterval(1)\n                            .fireImmune()\n                            .build(new ResourceLocation(FpvDroneMod.MODID, "fpv_drone").toString()));\n}\n',
    'src/main/java/com/example/fpvdrone/item/FpvDroneItem.java': 'package com.example.fpvdrone.item;\n\nimport com.example.fpvdrone.capability.PlayerDroneProvider;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.example.fpvdrone.network.PacketHandler;\nimport com.example.fpvdrone.network.S2CDroneTelemetryPacket;\nimport com.example.fpvdrone.registry.ModEntities;\nimport com.example.fpvdrone.registry.ModSounds;\nimport net.minecraft.core.BlockPos;\nimport net.minecraft.core.Direction;\nimport net.minecraft.server.level.ServerLevel;\nimport net.minecraft.server.level.ServerPlayer;\nimport net.minecraft.sounds.SoundSource;\nimport net.minecraft.world.InteractionResult;\nimport net.minecraft.world.entity.EquipmentSlot;\nimport net.minecraft.world.entity.player.Player;\nimport net.minecraft.world.item.Item;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraft.world.item.context.UseOnContext;\nimport net.minecraft.world.level.Level;\nimport net.minecraft.world.phys.Vec3;\n\npublic class FpvDroneItem extends Item {\n    public FpvDroneItem(Properties properties) {\n        super(properties);\n    }\n\n    @Override\n    public InteractionResult useOn(UseOnContext context) {\n        Level level = context.getLevel();\n        Player player = context.getPlayer();\n        if (player == null) {\n            return InteractionResult.PASS;\n        }\n\n        if (!(level instanceof ServerLevel serverLevel) || !(player instanceof ServerPlayer serverPlayer)) {\n            return InteractionResult.SUCCESS;\n        }\n\n        BlockPos clickedPos = context.getClickedPos();\n        Direction face = context.getClickedFace();\n        Vec3 spawnPos = Vec3.atCenterOf(clickedPos).add(\n                face.getStepX() * 0.75,\n                face.getStepY() * 0.75 + 0.45,\n                face.getStepZ() * 0.75\n        );\n\n        FpvDroneEntity drone = ModEntities.FPV_DRONE.get().create(serverLevel);\n        if (drone == null) {\n            return InteractionResult.FAIL;\n        }\n\n        drone.setPos(spawnPos.x, spawnPos.y, spawnPos.z);\n        drone.setOwnerUuid(serverPlayer.getUUID());\n        drone.setInitialYaw(serverPlayer.getYRot());\n        serverLevel.addFreshEntity(drone);\n\n        // Bind drone to PlayerDroneCapability (always, even if goggles are not worn yet)\n        serverPlayer.getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(cap ->\n                cap.bindDrone(drone.getUUID(), drone.getId()));\n\n        // Play ESC arming beep\n        serverLevel.playSound(null, serverPlayer.getX(), serverPlayer.getY(), serverPlayer.getZ(),\n                ModSounds.DRONE_ARM_BEEP.get(), SoundSource.PLAYERS, 0.85F, 1.0F);\n\n        // Only start piloting & switch camera if player is currently wearing FPV Goggles; otherwise park on ground\n        if (!(serverPlayer.getItemBySlot(EquipmentSlot.HEAD).getItem() instanceof FpvGogglesItem)) {\n            drone.setThrottle(0.0F);\n        }\n        ItemStack headStack = serverPlayer.getItemBySlot(EquipmentSlot.HEAD);\n        if (headStack.getItem() instanceof FpvGogglesItem) {\n            FpvGogglesItem.setBoundDroneUuid(headStack, drone.getUUID());\n            PacketHandler.sendToPlayer(\n                    new S2CDroneTelemetryPacket(\n                            drone.getId(),\n                            drone.getUUID(),\n                            drone.getThrottle(),\n                            drone.getBatteryVoltage(),\n                            drone.getFlightTicks(),\n                            true\n                    ),\n                    serverPlayer\n            );\n        }\n\n        if (!serverPlayer.getAbilities().instabuild) {\n            context.getItemInHand().shrink(1);\n        }\n\n        return InteractionResult.CONSUME;\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/event/ServerEvents.java': 'package com.example.fpvdrone.event;\n\nimport com.example.fpvdrone.FpvDroneMod;\nimport com.example.fpvdrone.capability.PlayerDroneCapability;\nimport com.example.fpvdrone.capability.PlayerDroneProvider;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.example.fpvdrone.item.FpvGogglesItem;\nimport com.example.fpvdrone.network.PacketHandler;\nimport com.example.fpvdrone.network.S2CDroneTelemetryPacket;\nimport net.minecraft.server.level.ServerLevel;\nimport net.minecraft.server.level.ServerPlayer;\nimport net.minecraft.world.entity.Entity;\nimport net.minecraft.world.entity.EquipmentSlot;\nimport net.minecraft.world.entity.player.Player;\nimport net.minecraft.world.item.ItemStack;\nimport net.minecraftforge.common.capabilities.RegisterCapabilitiesEvent;\nimport net.minecraftforge.event.AttachCapabilitiesEvent;\nimport net.minecraftforge.event.entity.living.LivingEquipmentChangeEvent;\nimport net.minecraftforge.event.entity.player.PlayerEvent;\nimport net.minecraftforge.eventbus.api.SubscribeEvent;\nimport net.minecraftforge.fml.common.Mod;\n\n@Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, bus = Mod.EventBusSubscriber.Bus.FORGE)\npublic class ServerEvents {\n    @SubscribeEvent\n    public static void onAttachCapabilities(AttachCapabilitiesEvent<Entity> event) {\n        if (event.getObject() instanceof Player) {\n            if (!event.getObject().getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).isPresent()) {\n                PlayerDroneProvider provider = new PlayerDroneProvider();\n                event.addCapability(PlayerDroneProvider.IDENTIFIER, provider);\n                event.addListener(provider::invalidate);\n            }\n        }\n    }\n\n    @SubscribeEvent\n    public static void onEquipmentChange(LivingEquipmentChangeEvent event) {\n        if (event.getSlot() != EquipmentSlot.HEAD) {\n            return;\n        }\n        if (!(event.getEntity() instanceof ServerPlayer serverPlayer)) {\n            return;\n        }\n        ItemStack newStack = event.getTo();\n        if (newStack.getItem() instanceof FpvGogglesItem) {\n            serverPlayer.getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(cap -> {\n                if (!cap.isPiloting()) {\n                    return;\n                }\n                ServerLevel level = serverPlayer.serverLevel();\n                Entity entity = level.getEntity(cap.getBoundDroneEntityId());\n                if (entity instanceof FpvDroneEntity drone && !drone.isRemoved()) {\n                    FpvGogglesItem.setBoundDroneUuid(newStack, drone.getUUID());\n                    PacketHandler.sendToPlayer(\n                            new S2CDroneTelemetryPacket(\n                                    drone.getId(),\n                                    drone.getUUID(),\n                                    drone.getThrottle(),\n                                    drone.getBatteryVoltage(),\n                                    drone.getFlightTicks(),\n                                    true\n                            ),\n                            serverPlayer\n                    );\n                } else {\n                    cap.clearBinding();\n                }\n            });\n        }\n    }\n\n    @SubscribeEvent\n    public static void onPlayerClone(PlayerEvent.Clone event) {\n        if (event.isWasDeath()) {\n            event.getOriginal().reviveCaps();\n            event.getOriginal().getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(oldCap ->\n                    event.getEntity().getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(newCap ->\n                            newCap.copyFrom(oldCap)));\n            event.getOriginal().invalidateCaps();\n        }\n    }\n\n    @SubscribeEvent\n    public static void onPlayerLoggedOut(PlayerEvent.PlayerLoggedOutEvent event) {\n        if (!(event.getEntity() instanceof ServerPlayer serverPlayer)) {\n            return;\n        }\n        serverPlayer.getCapability(PlayerDroneProvider.PLAYER_DRONE_CAP).ifPresent(cap -> {\n            if (cap.isPiloting()) {\n                ServerLevel level = serverPlayer.serverLevel();\n                Entity drone = level.getEntity(cap.getBoundDroneEntityId());\n                if (drone instanceof FpvDroneEntity fpvDrone && !fpvDrone.isRemoved()) {\n                    fpvDrone.discard();\n                }\n                cap.clearBinding();\n            }\n        });\n    }\n\n    @Mod.EventBusSubscriber(modid = FpvDroneMod.MODID, bus = Mod.EventBusSubscriber.Bus.MOD)\n    public static class ModBusEvents {\n        @SubscribeEvent\n        public static void onRegisterCapabilities(RegisterCapabilitiesEvent event) {\n            event.register(PlayerDroneCapability.class);\n        }\n    }\n}\n',
    'src/main/java/com/example/fpvdrone/client/ClientDroneState.java': 'package com.example.fpvdrone.client;\n\nimport com.example.fpvdrone.client.audio.DroneMotorSoundInstance;\nimport com.example.fpvdrone.client.audio.SignalStaticSoundInstance;\nimport com.example.fpvdrone.client.gui.FpvHudOverlay;\nimport com.example.fpvdrone.entity.FpvDroneEntity;\nimport com.example.fpvdrone.item.FpvGogglesItem;\nimport net.minecraft.client.Minecraft;\nimport net.minecraft.world.entity.Entity;\nimport net.minecraft.world.entity.EquipmentSlot;\n\nimport java.util.UUID;\n\npublic class ClientDroneState {\n    public static final float MAX_RANGE_METERS = 800.0F; // 50 chunks = 800 blocks\n\n    public enum Phase {\n        IDLE,\n        PILOTING,\n        FREEZE_FRAME,\n        NO_SIGNAL\n    }\n\n    private static Phase phase = Phase.IDLE;\n    private static int activeDroneId = -1;\n    private static UUID activeDroneUuid = null;\n    private static float throttle = 0.0F;\n    private static float batteryVoltage = 16.8F;\n    private static int flightTicks = 0;\n    private static float distanceMeters = 0.0F;\n    private static int phaseTimerTicks = 0;\n\n    private static float lastCamYaw = 0.0F;\n    private static float lastCamPitch = 0.0F;\n    private static float lastCamRoll = 0.0F;\n\n    private static DroneMotorSoundInstance motorSound;\n    private static SignalStaticSoundInstance staticSound;\n\n    public static Phase getPhase() {\n        return phase;\n    }\n\n    public static int getActiveDroneId() {\n        return activeDroneId;\n    }\n\n    public static float getThrottle() {\n        return throttle;\n    }\n\n    public static float getBatteryVoltage() {\n        return batteryVoltage;\n    }\n\n    public static int getFlightTicks() {\n        return flightTicks;\n    }\n\n    public static float getDistanceMeters() {\n        return distanceMeters;\n    }\n\n    public static float getLastCamYaw() {\n        return lastCamYaw;\n    }\n\n    public static float getLastCamPitch() {\n        return lastCamPitch;\n    }\n\n    public static float getLastCamRoll() {\n        return lastCamRoll;\n    }\n\n    public static void setLastCamAngles(float yaw, float pitch, float roll) {\n        lastCamYaw = yaw;\n        lastCamPitch = pitch;\n        lastCamRoll = roll;\n    }\n\n    public static boolean isPiloting() {\n        return phase == Phase.PILOTING;\n    }\n\n    public static boolean isPilotingOrTransitioning() {\n        return phase != Phase.IDLE;\n    }\n\n    public static void onTelemetryReceived(int droneId, UUID droneUuid, float newThrottle,\n                                            float newBattery, int newFlightTicks, boolean initialBind) {\n        Minecraft mc = Minecraft.getInstance();\n        if (initialBind) {\n            phase = Phase.PILOTING;\n            activeDroneId = droneId;\n            activeDroneUuid = droneUuid;\n            phaseTimerTicks = 0;\n            if (mc.level != null) {\n                Entity e = mc.level.getEntity(droneId);\n                if (e instanceof FpvDroneEntity drone) {\n                    mc.setCameraEntity(drone);\n                    startMotorSound(drone);\n                }\n            }\n        }\n        if (phase == Phase.PILOTING && (activeDroneId == droneId || initialBind)) {\n            throttle = newThrottle;\n            batteryVoltage = newBattery;\n            flightTicks = newFlightTicks;\n        }\n    }\n\n    public static void onDroneDestroyed(double ix, double iy, double iz) {\n        triggerSignalLost();\n    }\n\n    public static void triggerSignalLost() {\n        if (phase == Phase.FREEZE_FRAME || phase == Phase.NO_SIGNAL) {\n            return;\n        }\n        Minecraft mc = Minecraft.getInstance();\n        FpvHudOverlay.captureFreezeFrame();\n        stopMotorSound();\n        phase = Phase.FREEZE_FRAME;\n        phaseTimerTicks = 10; // 0.5 seconds at 20 TPS\n        if (mc.player != null && mc.getCameraEntity() == null) {\n            mc.setCameraEntity(mc.player);\n        }\n    }\n\n    public static void tick() {\n        Minecraft mc = Minecraft.getInstance();\n        if (mc.level == null || mc.player == null) {\n            resetImmediate();\n            return;\n        }\n\n        if (phase == Phase.PILOTING) {\n            // If player takes off goggles, return camera to player immediately\n            if (!(mc.player.getItemBySlot(EquipmentSlot.HEAD).getItem() instanceof FpvGogglesItem)) {\n                resetImmediate();\n                return;\n            }\n            Entity entity = mc.level.getEntity(activeDroneId);\n            if (!(entity instanceof FpvDroneEntity drone) || drone.isRemoved()) {\n                triggerSignalLost();\n                return;\n            }\n            if (mc.getCameraEntity() != drone) {\n                mc.setCameraEntity(drone);\n            }\n            if (motorSound == null || motorSound.isStopped()) {\n                startMotorSound(drone);\n            }\n            distanceMeters = (float) mc.player.position().distanceTo(drone.position());\n            if (distanceMeters >= MAX_RANGE_METERS) {\n                triggerSignalLost();\n                return;\n            }\n        } else if (phase == Phase.FREEZE_FRAME) {\n            phaseTimerTicks--;\n            if (phaseTimerTicks <= 0) {\n                phase = Phase.NO_SIGNAL;\n                phaseTimerTicks = 40; // 2.0 seconds (0.5s -> 2.5s)\n                startStaticSound();\n            }\n        } else if (phase == Phase.NO_SIGNAL) {\n            phaseTimerTicks--;\n            if (phaseTimerTicks <= 0) {\n                resetImmediate();\n            }\n        }\n    }\n\n    public static void resetImmediate() {\n        Minecraft mc = Minecraft.getInstance();\n        phase = Phase.IDLE;\n        activeDroneId = -1;\n        activeDroneUuid = null;\n        throttle = 0.0F;\n        distanceMeters = 0.0F;\n        phaseTimerTicks = 0;\n        stopMotorSound();\n        stopStaticSound();\n        FpvHudOverlay.clearFreezeFrame();\n        if (mc.player != null && mc.getCameraEntity() != mc.player) {\n            mc.setCameraEntity(mc.player);\n        }\n    }\n\n    private static void startMotorSound(FpvDroneEntity drone) {\n        stopMotorSound();\n        motorSound = new DroneMotorSoundInstance(drone);\n        Minecraft.getInstance().getSoundManager().play(motorSound);\n    }\n\n    private static void stopMotorSound() {\n        if (motorSound != null) {\n            motorSound.stopSound();\n            motorSound = null;\n        }\n    }\n\n    private static void startStaticSound() {\n        stopStaticSound();\n        staticSound = new SignalStaticSoundInstance();\n        Minecraft.getInstance().getSoundManager().play(staticSound);\n    }\n\n    private static void stopStaticSound() {\n        if (staticSound != null) {\n            staticSound.stopSound();\n            staticSound = null;\n        }\n    }\n}\n',
}
for k, v in PATCH.items():
    p = pathlib.Path(k)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(v, encoding="utf-8")
print("Patched", len(PATCH), "files")
